INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-3-invu', 'Partners INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('El Manejo de la Objeción "No Necesito Cambiar" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "no necesito cambiar mi sistema". La respuesta es validar su postura, pero luego preguntar: "¿Tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? ¿Tienes e-commerce propio sin comisiones?" Si el cliente responde que no, el Partner puede mostrar que INVU es una mejora, no solo un cambio.', 'Un Partner le dice a un restaurador: "Entiendo. Pero ¿tienes control de inventario en tiempo real? ¿Tu facturación electrónica está integrada o pagas aparte? ¿Puedes centralizar tus sedes y ver reportes consolidados? ¿Tienes e-commerce propio sin comisiones? INVU hace todo eso en un solo sistema. Te recomiendo que al menos los conozcas, no pierdes nada." El restaurador, que paga Nubefact aparte y no centraliza su inventario, acepta la reunión.', 31),
('El Manejo de la Objeción "Es Caro" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "es caro". La respuesta es validar su preocupación, pero luego mostrar que cuando se suman los costos de facturación electrónica aparte, soporte, sistemas separados, y comisiones de delivery apps, INVU termina siendo más barato o igual. Además, el control de inventario y la reducción de mermas pagan la inversión.', 'Un Partner le dice a un restaurador: "Yo conozco el sistema y sé que cuando sumas lo que pagas por facturación electrónica aparte, por soporte, por sistemas separados, y por comisiones de delivery apps, termina siendo más barato o igual. Además, el control que te da en inventario y la reducción de mermas pagan la inversión. Vale la pena conocerlos." El restaurador, que no había sumado todos los costos, acepta la reunión.', 32),
('El Manejo de la Objeción "Lo Voy a Pensar" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice "lo voy a pensar". La respuesta es validar que es normal, pero ofrecer una demo sin compromiso: "Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada." Esto quita presión y permite que el cliente avance en el proceso sin sentirse forzado.', 'Un Partner le dice a un restaurador: "Es normal. Te propongo que los conozcas en una demo sin compromiso. Después de eso, si lo piensas y decides que no es para ti, no pasa nada. ¿Qué te parece?" El restaurador, que se sentía presionado a decidir, se relaja y acepta la demo.', 33),
('El Manejo de la Objeción "Ya Tengo un Amigo que me Recomendó Otro Sistema" para el Partner', 'El Partner debe manejar la objeción del potencial cliente que dice que ya tiene otra recomendación. La respuesta es no descalificar la otra opción, sino ofrecer una comparación informada: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada."', 'Un Partner le dice a un restaurador: "Perfecto, lo importante es que encuentres la solución que mejor se adapte a ti. Te recomiendo que también conozcas a INVU para comparar. Así tomas una decisión informada. ¿Te parece?" El restaurador, que no quería cerrarse a una sola opción, acepta conocer a INVU.', 34),
('El Manejo de la Objeción del Partner "No Sé Vender"', 'El Partner que dice "no sé vender" debe recordar que no necesita vender. Solo necesita abrir la puerta y presentar a INVU. INVU es el que cierra. El único trabajo del Partner es conectar y asegurar la reunión. Eso lo puede hacer cualquier profesional con contactos en la industria, sin importar su experiencia en ventas. Además, el 8% del valor del primer año del cliente es una comisión justa por abrir esa puerta. Vale la pena el esfuerzo.', 'Un contador duda en referir a sus clientes porque cree que necesita saber vender. Pero luego recuerda: "No necesito vender. Solo necesito abrir la puerta y presentar a INVU. INVU es el que cierra. Mi único trabajo es conectar y asegurar la reunión. Además, el 8% del valor del primer año del cliente es una comisión justa por abrir esa puerta." Con esta mentalidad, contacta a su primer cliente restaurantero y agenda una reunión con INVU.', 35),
('Los Niveles de Dominio del Partner', 'El Partner pasa por 4 niveles: Básico (identifica oportunidades pero no las registra, pierde comisiones), Medio (presenta y registra, protege su comisión), Alto (construye una red activa, refiere negocios regularmente, genera S/10,000+ anuales), y Gravedad Cero (se convierte en partner estratégico, con ingresos recurrentes, reconocimiento de INVU, y comisiones que superan los S/20,000 anuales). El objetivo es llegar a Gravedad Cero: ser un socio estratégico de INVU.', 'Básico: Conoce a un restaurador pero no lo refiere formalmente. Pierde la comisión.
Medio: Refiere a un restaurador de 3 sedes, registra la oportunidad, y cobra S/1,992.
Alto: Refiere a 5 clientes al año, todos registrados, ganando S/9,960 anuales.
Gravedad Cero: Tiene una red de 20 contactos en la industria, refiere 10 negocios al año (incluyendo cuentas grandes), gana S/50,000+ anuales, e INVU lo reconoce como un aliado de crecimiento. Su recomendación tiene peso en la industria.', 36),
('El Potencial de Ingresos Ilimitado del Partner', 'El Partner puede referir múltiples negocios y acumular comisiones sin límite. No hay tope de ingresos ni restricción de cantidad de referidos. Cuantos más negocios conecte, más comisiones acumula. Si refiere negocios grandes (3-10 sedes), sus comisiones pueden superar los S/20,000 o S/50,000 anuales. El potencial de ingresos es ilimitado y está directamente ligado al tamaño y cantidad de los negocios que refiere.', 'Un Partner refiere 5 negocios de 3 sedes al año: 5 x S/1,992 = S/9,960.
Si refiere 3 cadenas de 10 sedes: 3 x S/6,057 = S/18,171.
Si refiere 2 cuentas estratégicas con comisión preferente: 2 x S/10,560+ = S/21,120+.
Si refiere múltiples clientes y acumula más de 20 sucursales en 3 meses, gana bonos de S/2,000 adicionales.
El potencial de ingresos es ilimitado. El Partner que construye una red activa y refiere negocios grandes puede generar ingresos equivalentes a un salario anual completo con un esfuerzo mínimo.', 37),
('El Programa Partners como Extensión del Equipo de Ventas', 'El programa de partners convierte a los partners en una extensión del equipo de ventas de INVU, ampliando su alcance en el mercado peruano sin costo fijo. Los partners abren puertas que el equipo comercial no podría abrir por sí mismo, aprovechando la confianza y las relaciones personales en la industria. Esto acelera el crecimiento de INVU y genera beneficios para todos. Los partners ganan comisiones significativas; INVU gana clientes calificados; el ecosistema crece.', 'El equipo de ventas de INVU no puede contactar a todos los restaurantes de Lima. Pero 100 partners, cada uno con 10 contactos en la industria, pueden abrir 1,000 puertas. El programa de partners multiplica el alcance comercial de INVU, generando más oportunidades de venta y más ingresos para los partners. INVU crece; los partners cobran comisiones; la red se expande. Todos ganan.


# PÍLDORAS DE CONOCIMIENTO - PROGRAMA HUNTERS INVU POS PERÚ', 38),
('El Hunter – Cazador, No Esperador', 'El Hunter no espera leads; sale a la calle a identificar negocios, contactar tomadores de decisión, presentar el valor de INVU y cerrar ventas. El Hunter es un cazador de oportunidades que construye su propio mercado. Su ingreso depende directamente de su esfuerzo: 15 visitas/semana, 10 reuniones con decisores, 5 demos/mes, 2-3 cierres/mes. El que no visita, no vende.', 'Un Hunter inicia su semana con una agenda de 15 visitas a restaurantes. No espera que el teléfono suene; sale a la calle, entra a los locales, identifica al dueño o gerente, y hace su pitch. En la primera semana, logra 5 reuniones. En la segunda, 3 demos. En la tercera, 2 cierres. Su ingreso: S/4,298. El Hunter que espera, no cobra. El que caza, triunfa.', 39),
('El Ritmo del Hunter Ganador – La Disciplina que Multiplica Ingresos', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito. El ritmo es la disciplina que separa al Hunter promedio del Hunter Elite.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base S/2,958 + comisiones S/490 + bono S/850 + MRR S/252 = S/4,550. El esfuerzo se traduce en dinero. El que no visita, no vende.', 40),
('El Pitch de 30 Segundos – La Puerta de Entrada', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?". El pitch debe memorizarse y adaptarse al contexto del cliente.', 'Un Hunter entra a un restaurante y dice: "INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable." El dueño, que ha estado batallando con su facturación electrónica, responde: "¿Cómo lo vemos?" El Hunter ya tiene la reunión.', 41),
('Las 7 Preguntas del Hunter – El Mapa del Tesoro', 'El Hunter tiene 7 preguntas que revelan la calificación del cliente, sus dolores y los módulos que necesita. Sin estas preguntas, el Hunter está navegando sin mapa. Las preguntas cubren: facturación y sedes, sistema actual y dolor, facturación electrónica, recetas costeadas, número de cajas, delivery y ecommerce, y tomador de decisión y timeline. El diagnóstico es el mapa; el cierre es el tesoro.', 'En una primera reunión, el Hunter hace las 7 preguntas en 5 minutos. Descubre que el cliente tiene 3 sedes, paga Nubefact aparte, no tiene recetas costeadas, y quiere implementar QR y fidelización. El Hunter sabe exactamente qué cotizar: INVU Central + 3 licencias Sucursal + QR + Loyalty. El diagnóstico es el mapa; el cierre es el tesoro.', 42),
('La Escalera Base – Protección y Motivación para el Hunter', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas. La escalera es el colchón que permite al Hunter aprender y crecer sin miedo.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258. No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', 43),
('Comisiones desde la Venta 4 – El Ingreso sin Techo', 'Desde la cuarta venta, el Hunter gana 10% sobre setup facturado y pagado, 3% MRR mensual sobre licencias activas durante 12 meses, y 3% sobre hardware. Las comisiones se suman a la base, no la reemplazan. El ingreso del Hunter no tiene techo: cada venta adicional es puro ingreso incremental. Es el combustible que impulsa al Hunter a buscar más y más ventas.', 'Un Hunter cierra 7 ventas en un mes. Base: S/2,958. Comisiones de setup de las ventas 4 a 7: 10% de S/700 = S/980. Bono Top Performer: S/1,020. Cola MRR de las licencias activas: S/504. Ingreso total: S/5,462. Cada venta adicional es puro ingreso extra. No hay techo.', 44)) AS t(concepto, enseñanza, ejemplo, orden);